import{_ as l,a0 as p,w as o,s as d,ao as h,I as t,x as e,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何在 Debian/Ubuntu 系统中检查程序包是否安装？ | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Debian/Ubuntu 系统中检查程序包是否安装？ | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Debian/Ubuntu 系统中检查程序包是否安装？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Debian/Ubuntu 系统中检查程序包是否安装？ | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190513 How To Check Whether The Given Package Is Installed Or Not On Debian-Ubuntu System","title":"如何在 Debian/Ubuntu 系统中检查程序包是否安装？","tag":"201906","desc":""},"relativePath":"201906/20190513 How To Check Whether The Given Package Is Installed Or Not On Debian-Ubuntu System.md","filePath":"[post].md"}'),r={name:"201906/20190513 How To Check Whether The Given Package Is Installed Or Not On Debian-Ubuntu System.md"};function c(g,a,u,b,k,m){const s=p("Link");return o(),d("div",null,[a[15]||(a[15]=h(`<h1 id="如何在-debian-ubuntu-系统中检查程序包是否安装" tabindex="-1">如何在 Debian/Ubuntu 系统中检查程序包是否安装？ <a class="header-anchor" href="#如何在-debian-ubuntu-系统中检查程序包是否安装" aria-label="Permalink to “如何在 Debian/Ubuntu 系统中检查程序包是否安装？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201906/23/235541yl41p73z5jv78y8p.jpg" alt=""></p><p>我们近期发布了一篇关于批量程序包安装的文章。在此同时，关于如何获取系统上已安装了的程序包信息，我也做了些调查然后找到了些方法。我会把这些方法分享在我们的网站上，希望能帮助到其他人。</p><p>有很多种方法可以检查程序包是否已安装，我找到了 7 种命令，你可以从中选择你喜欢的使用。</p><p>如下：</p><ul><li><code>apt-cache</code>：可用于查询 APT 缓存或程序包的元数据。</li><li><code>apt</code>：是基于 Debian 的系统中的安装、下载、删除、搜索和管理包的强有力的工具。</li><li><code>dpkg-query</code>：一个查询 dpkg 数据库的工具。</li><li><code>dpkg</code>：基于 Debian 的系统的包管理工具。</li><li><code>which</code>：返回在终端中输入命令时执行的可执行文件的全路径。</li><li><code>whereis</code>：可用于搜索指定命令的二进制文件、源码文件和帮助文件。</li><li><code>locate</code>：比 <code>find</code> 命令快，因为其使用 <code>updatedb</code> 数据库搜索，而 <code>find</code>命令在实际系统中搜索。</li></ul><h3 id="方法一、使用-apt-cache-命令" tabindex="-1">方法一、使用 apt-cache 命令 <a class="header-anchor" href="#方法一、使用-apt-cache-命令" aria-label="Permalink to “方法一、使用 apt-cache 命令”">​</a></h3><p><code>apt-cache</code> 命令用于从 APT 内部数据库中查询<strong>APT 缓存</strong>和<strong>包的元数据</strong>，将会搜索和显示指定包的信息，包括是否安装、程序包版本、源码仓库信息等。</p><p>下面的示例清楚的显示 <code>nano</code> 包已经在系统中安装了以及对应安装的版本号。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-cache policy nano</span></span>
<span class="line"><span>nano:</span></span>
<span class="line"><span>  Installed: 2.9.3-2</span></span>
<span class="line"><span>  Candidate: 2.9.3-2</span></span>
<span class="line"><span>  Version table:</span></span>
<span class="line"><span> *** 2.9.3-2 500</span></span>
<span class="line"><span>        500 http://in.archive.ubuntu.com/ubuntu bionic/main amd64 Packages</span></span>
<span class="line"><span>        100 /var/lib/dpkg/status</span></span></code></pre></div><h3 id="方法二、使用-apt-命令" tabindex="-1">方法二、使用 apt 命令 <a class="header-anchor" href="#方法二、使用-apt-命令" aria-label="Permalink to “方法二、使用 apt 命令”">​</a></h3><p><code>apt</code> 是一个功能强大的命令行工具，可用于安装、下载、删除、搜索、管理程序包以及查询关于程序包的信息，类似对于 <code>libapt-pkg</code> 库的所有功能的底层访问。其包含一些与包管理相关的但很少用到的命令行功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt -qq list nano</span></span>
<span class="line"><span>nano/bionic,now 2.9.3-2 amd64 [installed]</span></span></code></pre></div><h3 id="方法三、使用-dpkg-query-命令" tabindex="-1">方法三、使用 dpkg-query 命令 <a class="header-anchor" href="#方法三、使用-dpkg-query-命令" aria-label="Permalink to “方法三、使用 dpkg-query 命令”">​</a></h3><p><code>dpkg-query</code> 是显示 <code>dpkg</code> 数据库中程序包信息列表的一个工具。</p><p>下面示例中的输出的第一列 <code>ii</code>，表示查询的程序包已安装了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dpkg-query --list | grep -i nano</span></span>
<span class="line"><span>ii  nano    2.9.3-2    amd64    small, friendly text editor inspired by Pico</span></span></code></pre></div><h3 id="方法四、使用-dpkg-命令" tabindex="-1">方法四、使用 dpkg 命令 <a class="header-anchor" href="#方法四、使用-dpkg-命令" aria-label="Permalink to “方法四、使用 dpkg 命令”">​</a></h3><p><code>dpkg</code>（<strong>d</strong>ebian <strong>p</strong>ac<strong>k</strong>a<strong>g</strong>e）是一个安装、构建、删除和管理 Debian 包的工具，但和其他包管理系统不同的是，其不能自动下载和安装包或包依赖。</p><p>下面示例中的输出的第一列 <code>ii</code>，表示查询的包已安装了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dpkg -l | grep -i nano</span></span>
<span class="line"><span>ii  nano     2.9.3-2    amd64   small, friendly text editor inspired by Pico</span></span></code></pre></div><h3 id="方法五、使用-which-命令" tabindex="-1">方法五、使用 which 命令 <a class="header-anchor" href="#方法五、使用-which-命令" aria-label="Permalink to “方法五、使用 which 命令”">​</a></h3><p><code>which</code> 命令返回在终端中输入命令时执行的可执行文件的全路径。这对于你想要给可执行文件创建桌面快捷方式或符号链接时非常有用。</p><p><code>which</code> 命令仅在当前用户 <code>PATH</code> 环境变量配置的目录列表中搜索，而不是在所有用户的目录中搜索。这意思是当你登入你自己账号时，其不会在 <code>root</code> 用户文件或目录中搜索。</p><p>如果对于指定的程序包或可执行文件路径有如下输出，则表示已安装了，否则没有。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># which nano</span></span>
<span class="line"><span>/bin/nano</span></span></code></pre></div><h3 id="方法六、使用-whereis-命令" tabindex="-1">方法六、使用 whereis 命令 <a class="header-anchor" href="#方法六、使用-whereis-命令" aria-label="Permalink to “方法六、使用 whereis 命令”">​</a></h3><p><code>whereis</code> 命令用于针对指定命令搜索对应的程序二进制文件、源码文件以及帮助文件等。</p><p>如果对于指定的程序包或可执行文件路径有如下输出，则表示已安装了，否则没有。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># whereis nano</span></span>
<span class="line"><span>nano: /bin/nano /usr/share/nano /usr/share/man/man1/nano.1.gz /usr/share/info/nano.info.gz</span></span></code></pre></div><h3 id="方法七、使用-locate-命令" tabindex="-1">方法七、使用 locate 命令 <a class="header-anchor" href="#方法七、使用-locate-命令" aria-label="Permalink to “方法七、使用 locate 命令”">​</a></h3><p><code>locate</code> 命令比 <code>find</code> 命令快，因为其在 <code>updatedb</code> 数据库中搜索，而 <code>find</code> 命令在实际系统中进行搜索。</p><p>对于获取指定文件，其使用数据库而不是在特定目录路径中搜索。</p><p><code>locate</code> 命令不会预安装在大多数系统中，需要手动安装。</p><p><code>locate</code> 使用的数据库会根据定时任务定期更新。当然，我们也可以手动更新。</p><p>如果对于指定的程序包或可执行文件路径有如下输出，则表示已安装了，否则没有。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># locate --basename &#39;\\nano&#39;</span></span>
<span class="line"><span>/usr/bin/nano</span></span>
<span class="line"><span>/usr/share/nano</span></span>
<span class="line"><span>/usr/share/doc/nano</span></span></code></pre></div><hr>`,38)),t("p",null,[a[1]||(a[1]=e("via: ",-1)),n(s,{href:"https://www.2daygeek.com/how-to-check-whether-the-given-package-is-installed-or-not-on-ubuntu-debian-system/"},{default:i(()=>[...a[0]||(a[0]=[e("https://www.2daygeek.com/how-to-check-whether-the-given-package-is-installed-or-not-on-ubuntu-debian-system/",-1)])]),_:1})]),t("p",null,[a[6]||(a[6]=e("作者：",-1)),n(s,{href:"https://www.2daygeek.com/author/magesh/"},{default:i(()=>[...a[2]||(a[2]=[e("Magesh Maruthamuthu",-1)])]),_:1}),a[7]||(a[7]=e(" 选题：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[3]||(a[3]=[e("lujun9972",-1)])]),_:1}),a[8]||(a[8]=e(" 译者：",-1)),n(s,{href:"https://github.com/yizhuoyan"},{default:i(()=>[...a[4]||(a[4]=[e("yizhuoyan",-1)])]),_:1}),a[9]||(a[9]=e(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:i(()=>[...a[5]||(a[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[a[12]||(a[12]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原创编译，",-1)),n(s,{href:"https://linux.cn/"},{default:i(()=>[...a[11]||(a[11]=[e("Linux中国",-1)])]),_:1}),a[14]||(a[14]=e(" 荣誉推出",-1))])])}const C=l(r,[["render",c]]);export{w as __pageData,C as default};
